def tau_n_12(n):
    if n == 1:
        return 1
    # Prime factorization of n
    d = 2
    temp = n
    factors = {}
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    # Compute tau(n^12)
    res = 1
    for p in factors:
        res *= (12 * factors[p] + 1)
    return res

candidates = [1, 13, 25, 325]
for n in candidates:
    print(f"n={n}, tau(n^12)={tau_n_12(n)}")

def check_n(n):
    # Calculate tau(n^12)
    d = 2
    temp = n
    factors = {}
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    tau_n12 = 1
    for p in factors:
        tau_n12 *= (12 * factors[p] + 1)

    return tau_n12 == n

# Search for n up to 100,000 (arbitrary limit)
# Only check n such that n % 12 == 1
solutions = []
for n in range(1, 100000, 12):
    if check_n(n):
        solutions.append(n)
print(solutions)
